namespace sv_3ac0bb5806034f4bb19b8a8288484973.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state.
/// In Interactive Server mode, "scoped" means per-circuit, so each user
/// gets independent state that survives enhanced-nav page transitions.
/// </summary>
public class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }

    public void SetAll(ThemeMode theme, string accentColor)
    {
        var changed = Theme != theme || AccentColor != accentColor;
        Theme = theme;
        AccentColor = accentColor;
        if (changed) OnChange?.Invoke();
    }
}

// Applies theme to the document so both static and interactive elements reflect it.
export function applyTheme(theme, accentColor) {
    const root = document.documentElement;
    root.setAttribute("data-theme", theme.toLowerCase());
    root.style.setProperty("--accent-color", accentColor);
}

