// Applies theme to the document so both static and interactive elements reflect it.
export function applyTheme(theme, accentColor) {
    const root = document.documentElement;
    root.setAttribute("data-theme", theme.toLowerCase());
    root.style.setProperty("--accent-color", accentColor);
}

@*
    ThemeProvider: An interactive island placed in the static MainLayout.
    It subscribes to ThemeService.OnChange and pushes theme values into
    the DOM via JS interop, so that ALL rendered HTML (static or interactive)
    reflects the current theme.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

@code {
    private IJSObjectReference? _module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/theme.js");

            ThemeService.OnChange += OnThemeChanged;

            // Apply the current theme immediately on first render.
            await ApplyThemeAsync();
        }
    }

    private async void OnThemeChanged()
    {
        await InvokeAsync(async () => await ApplyThemeAsync());
    }

    private async Task ApplyThemeAsync()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync(
                "applyTheme",
                ThemeService.Theme.ToString(),
                ThemeService.AccentColor);
        }
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

@*
    ThemeIndicator: An interactive island in the header that shows the
    current theme and lets users cycle through modes with a single click.
    Because it is interactive, it can subscribe to ThemeService events and
    re-render independently of the static layout.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" @onclick="CycleTheme" title="Click to change theme">
    @GetIcon() @ThemeService.Theme
    <span class="accent-dot" style="background-color: @ThemeService.AccentColor;"></span>
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void CycleTheme()
    {
        var next = ThemeService.Theme switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            _                => ThemeMode.Light
        };
        ThemeService.SetTheme(next);
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        _                => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <button class="btn @(ThemeService.Theme == mode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeService.SetTheme(mode)">
                @mode
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <input type="color"
           class="form-control form-control-color mb-3"
