html, body {
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
}

/* ── Theme variables ─────────────────────────────────── */
:root {
    --accent-color: #0d6efd;
}

[data-theme="dark"] {
    color-scheme: dark;
    --bs-body-bg: #1a1a2e;
    --bs-body-color: #e0e0e0;
    background-color: #1a1a2e;
    color: #e0e0e0;
}

[data-theme="light"] {
    color-scheme: light;
}

/* ── Theme indicator (header) ────────────────────────── */
.theme-indicator {
    cursor: pointer;
    user-select: none;
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.5rem;
    border-radius: 0.375rem;
    font-size: 0.85rem;
}

.theme-indicator:hover {
    background-color: rgba(0, 0, 0, 0.05);
}

.accent-dot {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

